insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fi', '/flags/history/fi-1860.svg', '1860-01-01', '1918-05-29', 'Drapeau au lion (grand-duché)', 'Lion flag (Grand Duchy)', 'Rouge au lion d''or des armoiries du grand-duché, ce drapeau non officiel est largement arboré sous la domination russe ; il sert brièvement de drapeau d''État après l''indépendance du 6 décembre 1917.', 'Red with the gold lion of the Grand Duchy''s arms, this unofficial flag was widely flown under Russian rule; it briefly served as the state flag after independence on 6 December 1917.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fi', '/flags/history/fi-1918.svg', '1918-05-29', '1920-01-01', 'Finlande indépendante (1918-1920)', 'Independent Finland (1918–1920)', 'Le 29 mai 1918, le Parlement adopte la croix bleue sur fond blanc, couleurs proposées dès 1862 par l''écrivain Zacharias Topelius ; le bleu, d''abord plus clair, est assombri en 1920.', 'On 29 May 1918 Parliament adopted the blue cross on white, colours suggested back in 1862 by the writer Zacharias Topelius; the blue, lighter at first, was darkened in 1920.');
